import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Standards","description":"","frontmatter":{},"headers":[],"relativePath":"reference/standards.md","filePath":"reference/standards.md","lastUpdated":1788439235000}`),a={name:`reference/standards.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="standards" tabindex="-1">Standards <a class="header-anchor" href="#standards" aria-label="Permalink to “Standards”">​</a></h1><p>What mcp-hub implements, in which direction, and where the limits are.</p><p>Two directions matter, and they are genuinely different problems. <strong>Inbound</strong> is mcp-hub as an authorization server and resource server for the MCP clients that connect to it. <strong>Outbound</strong> is mcp-hub as an OAuth client toward the remote MCP servers it connects to on your behalf. Most gateways do one of the two.</p><h2 id="getting-a-client-identity" tabindex="-1">Getting a client identity <a class="header-anchor" href="#getting-a-client-identity" aria-label="Permalink to “Getting a client identity”">​</a></h2><p>The same four ways in and out — with one gap in each direction, named below.</p><table tabindex="0"><thead><tr><th></th><th>Inbound (a client → the hub)</th><th>Outbound (the hub → an upstream)</th></tr></thead><tbody><tr><td><strong>Operator-issued credentials</strong></td><td><code>mcp-hub-admin clients add</code> issues a <code>client_id</code> and secret by hand</td><td><code>oauth.mode: &quot;static&quot;</code> with a <code>clientId</code> the upstream gave you</td></tr><tr><td><strong>Dynamic registration</strong> (<a href="https://www.rfc-editor.org/rfc/rfc7591" target="_blank" rel="noreferrer">RFC 7591</a>)</td><td><code>POST /register</code>, on by default</td><td><code>oauth.mode: &quot;dcr&quot;</code></td></tr><tr><td><strong>Registration management</strong> (<a href="https://www.rfc-editor.org/rfc/rfc7592" target="_blank" rel="noreferrer">RFC 7592</a>)</td><td><code>GET</code>/<code>PUT</code>/<code>DELETE /register/&lt;client_id&gt;</code></td><td>the hub deletes its own registration on <code>upstream logout</code></td></tr><tr><td><strong>Client ID Metadata Documents</strong></td><td>a client uses its document URL as <code>client_id</code></td><td><code>oauth.mode: &quot;cimd&quot;</code>, one document per upstream</td></tr><tr><td><strong>Bearer token, no OAuth</strong></td><td><a href="/guide/clients#api-tokens">API tokens</a> minted by the operator</td><td>a static <code>Authorization</code> header</td></tr></tbody></table><p>CIMD is <a href="https://datatracker.ietf.org/doc/html/draft-ietf-oauth-client-id-metadata-document-00" target="_blank" rel="noreferrer"><code>draft-ietf-oauth-client-id-metadata-document-00</code></a>, the mechanism the MCP specification prefers over dynamic registration.</p><h2 id="proving-that-identity" tabindex="-1">Proving that identity <a class="header-anchor" href="#proving-that-identity" aria-label="Permalink to “Proving that identity”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Inbound</th><th>Outbound</th></tr></thead><tbody><tr><td><code>client_secret_post</code></td><td>✅</td><td>✅</td></tr><tr><td><code>client_secret_basic</code></td><td>❌ — credentials are read from the form body only</td><td>✅</td></tr><tr><td><code>none</code> (public client)</td><td>✅</td><td>✅</td></tr><tr><td><code>private_key_jwt</code> (<a href="https://www.rfc-editor.org/rfc/rfc7523" target="_blank" rel="noreferrer">RFC 7523</a>)</td><td>✅ <strong>for metadata-document clients only</strong></td><td>✅ via <code>oauth.clientAuth</code></td></tr></tbody></table><p>Both directions sign and verify RS/PS/ES 256/384/512 and EdDSA. Outbound, the hub signs with an Ed25519 key of its own at <code>&lt;DATA_PATH&gt;/upstream-key.pem</code> — deliberately not the key that signs the access tokens it issues — and publishes the public half in the document or registration the upstream reads.</p><h2 id="grants" tabindex="-1">Grants <a class="header-anchor" href="#grants" aria-label="Permalink to “Grants”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Inbound</th><th>Outbound</th></tr></thead><tbody><tr><td><code>authorization_code</code> + <a href="https://www.rfc-editor.org/rfc/rfc7636" target="_blank" rel="noreferrer">PKCE</a></td><td>✅ <strong>S256 required</strong>, <code>plain</code> rejected</td><td>✅ S256</td></tr><tr><td><code>refresh_token</code></td><td>✅ rotating, with reuse detection</td><td>✅ serialized, single-flight</td></tr><tr><td><code>client_credentials</code></td><td>❌</td><td>✅</td></tr></tbody></table><p>Inbound refresh tokens rotate on every use and are grouped into families: replaying a retired token revokes the whole family, because a replay means two parties hold one chain. Outbound, refresh is deliberately taken away from the SDK and serialized per upstream — parallel requests that each hit a <code>401</code> would otherwise each spend the same rotating token, which an upstream that detects reuse treats exactly as above.</p><h2 id="discovery-and-binding" tabindex="-1">Discovery and binding <a class="header-anchor" href="#discovery-and-binding" aria-label="Permalink to “Discovery and binding”">​</a></h2><table tabindex="0"><thead><tr><th>Standard</th><th>Inbound</th><th>Outbound</th></tr></thead><tbody><tr><td><a href="https://www.rfc-editor.org/rfc/rfc8414" target="_blank" rel="noreferrer">RFC 8414</a> authorization server metadata</td><td>✅ served, incl. the path-inserted form</td><td>✅ consumed</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc9728" target="_blank" rel="noreferrer">RFC 9728</a> protected resource metadata</td><td>✅ served, incl. path-scoped variants</td><td>✅ consumed, to find the upstream&#39;s authorization server</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc8707" target="_blank" rel="noreferrer">RFC 8707</a> resource indicators</td><td>✅ <strong>enforced by default</strong></td><td>✅ sent when the upstream publishes RFC 9728</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc8252" target="_blank" rel="noreferrer">RFC 8252</a> native apps</td><td>✅ loopback redirects, port-flexible</td><td>n/a</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc7009" target="_blank" rel="noreferrer">RFC 7009</a> revocation</td><td>⚠️ refresh tokens only — see below</td><td>✅ best effort on <code>upstream logout</code></td></tr></tbody></table><p>Resource indicators are the reason a token issued for one server does not reach another. Every access token carries the resource as its audience, and every request is checked against the path it arrived on.</p><p><code>/.well-known/openid-configuration</code> is served as a byte-identical <strong>alias</strong> of the RFC 8414 document, because several clients probe it first. That is all it is: there is no ID token, no <code>userinfo</code>, no OIDC claims. Do not enable a client&#39;s &quot;OpenID Connect&quot; option against it.</p><h2 id="not-implemented" tabindex="-1">Not implemented <a class="header-anchor" href="#not-implemented" aria-label="Permalink to “Not implemented”">​</a></h2><p>Named explicitly, so you do not have to find out by trying:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Access-token revocation</strong></td><td><code>/revoke</code> accepts an access token and does nothing with it. Only refresh tokens are revoked there. To kill live access tokens, use <code>mcp-hub-admin clients revoke</code>, which sets a marker the verifier checks.</td></tr><tr><td><strong><code>client_credentials</code> inbound</strong></td><td>The hub issues tokens to a person who approved a client, not to a machine identity. Use an <a href="/guide/clients#api-tokens">API token</a> for that.</td></tr><tr><td><strong>Device authorization grant</strong> (<a href="https://www.rfc-editor.org/rfc/rfc8628" target="_blank" rel="noreferrer">RFC 8628</a>)</td><td>Neither direction.</td></tr><tr><td><strong><code>private_key_jwt</code> for dynamically registered clients</strong></td><td>Inbound it is accepted only from metadata-document clients. A DCR client uses its secret.</td></tr><tr><td><strong>DPoP</strong> (<a href="https://www.rfc-editor.org/rfc/rfc9449" target="_blank" rel="noreferrer">RFC 9449</a>), <strong>mTLS</strong> (<a href="https://www.rfc-editor.org/rfc/rfc8705" target="_blank" rel="noreferrer">RFC 8705</a>), <strong>PAR</strong> (<a href="https://www.rfc-editor.org/rfc/rfc9126" target="_blank" rel="noreferrer">RFC 9126</a>), <strong>token introspection</strong> (<a href="https://www.rfc-editor.org/rfc/rfc7662" target="_blank" rel="noreferrer">RFC 7662</a>), <strong>token exchange</strong> (<a href="https://www.rfc-editor.org/rfc/rfc8693" target="_blank" rel="noreferrer">RFC 8693</a>), <code>client_secret_jwt</code></td><td>None of them, in either direction.</td></tr><tr><td><strong>A published JWKS for the hub&#39;s own tokens</strong></td><td>Access tokens are EdDSA-signed and verified by the hub alone; there is no endpoint for a third party to verify them.</td></tr><tr><td><strong>Scopes as an authorization boundary</strong></td><td>Scopes are carried through but nothing is enforced on them. Authorization is by resource, not by scope.</td></tr><tr><td><strong>Users, roles, audit trails</strong></td><td>One shared password, no per-user identity. Every token&#39;s subject is the same. See <a href="/guide/security#what-the-hub-does-not-protect-against">what the hub does not protect against</a>.</td></tr><tr><td><strong>Per-user upstream tokens</strong></td><td>An upstream credential belongs to the deployment, not to the client that triggered the call. The hub does not act on behalf of individual users.</td></tr></tbody></table><h2 id="transport-and-protocol" tabindex="-1">Transport and protocol <a class="header-anchor" href="#transport-and-protocol" aria-label="Permalink to “Transport and protocol”">​</a></h2><p>Streamable HTTP, stateless — no session state to leak — with SSE accepted for upstreams that only speak that. Bearer tokens are read from the <code>Authorization</code> header only; there is no query-parameter or form-body form.</p><p>The hub speaks <strong>both</strong> MCP revisions on every endpoint, and the client picks:</p><table tabindex="0"><thead><tr><th>Revision</th><th>How it is chosen</th><th>Where</th></tr></thead><tbody><tr><td><strong><code>2026-07-28</code></strong></td><td><code>server/discover</code></td><td><code>/hub</code>, <code>/&lt;name&gt;/mcp</code>, <code>mcp-hub-stdio</code></td></tr><tr><td><strong><code>2025-11-25</code></strong></td><td><code>initialize</code></td><td>the same three</td></tr></tbody></table><p>Which one you are on is a wire detail. The rule the hub holds itself to is that a client cannot tell from the answers: same tools, same names, same endpoint.</p><h3 id="what-is-carried-per-revision" tabindex="-1">What is carried, per revision <a class="header-anchor" href="#what-is-carried-per-revision" aria-label="Permalink to “What is carried, per revision”">​</a></h3><p>Every row here has a test, and the ones that say <strong>no</strong> say so because there is no test that could pass — not because the detail was left out of the table. The hub has twice announced something it did not deliver (<code>listChanged</code>, <code>resources.subscribe</code>), and both cost more to find than they would have cost to admit.</p><table tabindex="0"><thead><tr><th>Traffic</th><th><code>2026-07-28</code></th><th><code>2025-11-25</code></th></tr></thead><tbody><tr><td><code>tools/list</code>, <code>tools/call</code></td><td>carried</td><td>carried</td></tr><tr><td><code>resources/list</code>, <code>resources/templates/list</code>, <code>resources/read</code></td><td>carried</td><td>carried</td></tr><tr><td><code>prompts/list</code>, <code>prompts/get</code></td><td>carried</td><td>carried</td></tr><tr><td><code>completion/complete</code></td><td>carried</td><td>carried</td></tr><tr><td>A tool&#39;s <code>outputSchema</code> and a result&#39;s <code>structuredContent</code></td><td>carried</td><td>carried, with the SEP-2106 wrap</td></tr><tr><td><strong>Elicitation</strong> — a child asking the person a question</td><td><strong>carried both ways</strong></td><td>not offered</td></tr><tr><td>Embedded <code>sampling/createMessage</code> or <code>roots/list</code> in a child&#39;s question</td><td>dropped, and named in the log</td><td>—</td></tr><tr><td><code>describe_connection</code>, where <code>MCP_DIAGNOSTICS</code> is on</td><td>answers, and reports this era</td><td>answers, and reports this era</td></tr><tr><td><strong><code>subscriptions/listen</code></strong> — a child&#39;s changes reaching a client</td><td><strong>carried</strong></td><td>not offered</td></tr><tr><td><code>listChanged</code> notifications (tools, prompts, resources)</td><td>delivered on a subscription</td><td>not advertised, not delivered</td></tr><tr><td><code>notifications/resources/updated</code></td><td>delivered on a subscription</td><td>not advertised, not delivered</td></tr><tr><td><code>resources/subscribe</code></td><td>removed from the revision</td><td>not advertised, refused</td></tr><tr><td><code>logging/setLevel</code>, <code>notifications/message</code></td><td>not advertised, no handler</td><td>not advertised, no handler</td></tr></tbody></table><p><strong>Subscriptions are the second row worth reading twice</strong>, for the same reason as the first. <code>subscriptions/listen</code> is a long-lived stream, which sounds like the one thing a stateless gateway cannot hold — but the state is the open HTTP response, not a session table. When the socket goes, so does the subscription, and nothing is left behind to leak. That is why this could be built without giving up the property the rest of the design rests on. See <a href="/guide/subscriptions">Subscriptions</a>.</p><p>To a <code>2025-11-25</code> client the hub offers none of it. That revision delivers changes unsolicited on a channel the stateless transport does not keep, and <code>resources/subscribe</code> needs the hub to remember who asked for what — so rather than announce a <code>listChanged</code> whose notification would never arrive, the hub stays quiet. The hub announced exactly that for a long time and it was a lie; the row above is what it says now.</p><p><code>logging</code> is the third. <code>logging/setLevel</code> never had a handler on either era, so a client that believed the advertisement got a <code>-32601</code> at call time. On <code>2026-07-28</code> the level is per-request <code>_meta</code> and there is no RPC left to implement; carrying <code>notifications/message</code> is separate work. Until it exists the capability is not offered.</p><p><strong>The structured-output row has a footnote.</strong> <code>2026-07-28</code> lets a tool&#39;s <code>outputSchema</code> describe any JSON value (SEP-2106); <code>2025-11-25</code> allows only an object, so a child whose schema describes an array or a number reaches a 2025 client with both the schema and the value wrapped in <code>{&quot;result&quot;: …}</code>. The hub does that wrapping where it is the one talking to the older client, and leaves it alone where the <em>child</em> already did it — a gateway that unwrapped somebody else&#39;s answer to make it look modern would be inventing a shape nobody sent. Object-rooted schemas, which is nearly all of them, are identical on both.</p><p>The hub&#39;s own meta-tools all use an object root for exactly this reason: with an array root a client could tell from the payload which revision it had been given, and the promise above is that it cannot.</p><p><strong>Elicitation is the row worth reading twice.</strong> It is what <a href="/guide/elicitation"><code>smtp-mcp</code></a> and <code>imap-mcp</code> use to put a question in front of a person before they send or delete something, and behind a gateway it used to have nowhere to go. On <code>2026-07-28</code> it does: the question is a <em>result</em>, the call ends, the person decides, and the client retries with the answer. Nothing is held open, which is exactly why a stateless hub can carry it. See <a href="/guide/elicitation">Elicitation</a>.</p><p>To a <code>2025-11-25</code> client over HTTP the hub does not offer it at all. That revision delivers a question as a server-initiated request, and a stateless hub has no channel for one — so rather than announce a capability whose answer would be dropped, the hub stays quiet and the child takes its own fallback. That is the same rule as the two rows above it, applied before the mistake instead of after.</p><p>The authorization behaviour follows the specification revision that made metadata documents the preferred registration mechanism and deprecated dynamic registration — which the hub still serves, because most clients still need it.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/subscriptions">Subscriptions</a> — what a client can watch, and what a nap costs</li><li><a href="/guide/client-registration">How clients register</a> — the inbound side in detail</li><li><a href="/guide/configuration#upstreams-that-speak-oauth">Upstreams that speak OAuth</a> — the outbound side</li><li><a href="/guide/security">Security</a> — the trust model around both</li></ul>`,38)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};